//! Parity: the view computed in Rust must be identical (as JSON) to the one the legacy JS
//! (`tests/parity/legado.js`) produces for the same data. The cases are generated by
//! `node tests/parity/generate.mjs`.

use std::fs;
use std::path::PathBuf;

use serde_json::Value;
use signal_aduana::domain::{compute_view, ViewInput};

/// First JSON path where two values differ.
fn first_difference(path: &str, rust: &Value, js: &Value) -> Option<String> {
    match (rust, js) {
        (Value::Object(a), Value::Object(b)) => {
            let mut keys: Vec<&String> = a.keys().chain(b.keys()).collect();
            keys.sort();
            keys.dedup();
            for k in keys {
                let p = format!("{path}/{k}");
                match (a.get(k), b.get(k)) {
                    (Some(x), Some(y)) => {
                        if let Some(d) = first_difference(&p, x, y) {
                            return Some(d);
                        }
                    }
                    (Some(x), None) => return Some(format!("{p}: Rust has {x}, the JS has no such field")),
                    (None, Some(y)) => return Some(format!("{p}: the JS has {y}, Rust has no such field")),
                    (None, None) => {}
                }
            }
            None
        }
        (Value::Array(a), Value::Array(b)) => {
            for (i, (x, y)) in a.iter().zip(b).enumerate() {
                if let Some(d) = first_difference(&format!("{path}/{i}"), x, y) {
                    return Some(d);
                }
            }
            (a.len() != b.len()).then(|| format!("{path}: different length (Rust {}, JS {})", a.len(), b.len()))
        }
        _ => (rust != js).then(|| format!("{path}: Rust {rust} != JS {js}")),
    }
}

#[test]
fn rust_matches_the_legacy_js() {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/parity/cases");
    let mut inputs: Vec<PathBuf> = fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("could not read {}: {e}", dir.display()))
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.file_name().and_then(|n| n.to_str()).is_some_and(|n| n.ends_with(".input.json")))
        .collect();
    inputs.sort();
    assert!(!inputs.is_empty(), "no parity cases in {}", dir.display());

    let mut failures = Vec::new();
    for path in &inputs {
        let name = path.file_name().unwrap().to_str().unwrap().trim_end_matches(".input.json").to_string();
        let expected_path = path.with_file_name(format!("{name}.expected.json"));
        let input: ViewInput = serde_json::from_str(&fs::read_to_string(path).unwrap())
            .unwrap_or_else(|e| panic!("case {name}: invalid input: {e}"));
        let expected: Value = serde_json::from_str(
            &fs::read_to_string(&expected_path).unwrap_or_else(|e| panic!("case {name}: missing {}: {e}", expected_path.display())),
        )
        .unwrap();
        let today = input.today.clone().unwrap_or_else(|| "2026-11-13".into());
        let view = compute_view(input, &today).unwrap_or_else(|e| panic!("case {name}: error while computing: {e}"));
        let actual = serde_json::to_value(&view).unwrap();
        if actual != expected {
            let d = first_difference("", &actual, &expected).unwrap_or_else(|| "(difference not located)".into());
            failures.push(format!("case {name}: {d}"));
        }
    }
    assert!(failures.is_empty(), "{} of {} cases differ:\n{}", failures.len(), inputs.len(), failures.join("\n"));
    println!("{} parity cases passed", inputs.len());
}
